/// Code emitters for the generated dictionary, typed tags and UIDs.
library;

import 'naming.dart';
import 'parse.dart';
import 'source.dart';
import 'value_types.dart';

const _header =
    '// GENERATED by dartdicom/tool/gen_dictionary from DICOM PS3.6/PS3.7 '
    '$release.\n// Do not edit; run `just dict` to regenerate.\n';

/// `lib/src/dictionary/dictionary.g.dart`: every entry, for VR lookup
/// (implicit VR) and keyword lookup.
String emitDictionary(List<Element> elements) {
  final b = StringBuffer(_header)
    ..writeln()
    ..writeln("import '../vr/vr.dart';")
    ..writeln("import 'dictionary_entry.dart';")
    ..writeln()
    ..writeln(
        '/// The DICOM Standard release the dictionary was generated from.')
    ..writeln("const dicomRelease = '$release';")
    ..writeln()
    ..writeln('/// Standard dictionary entries by tag number.')
    ..writeln('const Map<int, DictionaryEntry> standardEntries = {');
  for (final e in elements.where((e) => !e.isRepeater)) {
    b.writeln('  0x${e.tag}: ${_entry(e)},');
  }
  b
    ..writeln('};')
    ..writeln()
    ..writeln('/// Entries for tag ranges (repeating groups and elements).')
    ..writeln('const List<RepeaterEntry> repeaterEntries = [');
  for (final e in elements.where((e) => e.isRepeater)) {
    final match = e.tag.replaceAll('x', '0');
    final mask = e.tag.replaceAll(RegExp('[0-9A-F]'), 'F').replaceAll('x', '0');
    b.writeln('  RepeaterEntry(0x$match, 0x$mask, ${_entry(e)}),');
  }
  return (b..writeln('];')).toString();
}

String _entry(Element e) {
  final vrs = '[${e.vrs.map((v) => 'Vr.${v.code}').join(', ')}]';
  final retired = e.retired ? ', retired: true' : '';
  return 'DictionaryEntry($vrs, ${_str(e.vm)}, ${_str(e.keyword)}, '
      '${_str(e.name)}$retired)';
}

/// Elements that get a typed constant, and the reasons the rest don't.
final class TagPlan {
  final constants = <(String, Element, String)>[]; // identifier, element, type
  final groupFunctions = <(String, Element, String)>[];
  final skipped = <String, List<Element>>{};

  void skip(String reason, Element e) => (skipped[reason] ??= []).add(e);
}

TagPlan planTags(List<Element> elements) {
  final plan = TagPlan();
  final seen = <String, Element>{};
  for (final e in elements) {
    if (e.keyword.isEmpty) {
      plan.skip('no keyword (placeholder)', e);
      continue;
    }
    if (e.vrs.isEmpty) {
      plan.skip('no VR (item and delimitation tags)', e);
      continue;
    }
    final groupOnly = RegExp(r'^[0-9A-F]{2}xx[0-9A-F]{4}$').hasMatch(e.tag);
    if (e.isRepeater && !groupOnly) {
      plan.skip('repeating element range (no single typed tag)', e);
      continue;
    }
    final id = identifierFor(e.keyword);
    final clash = seen[id];
    if (clash != null) {
      throw StateError('identifier "$id" from both ${clash.keyword} '
          '(${clash.tag}) and ${e.keyword} (${e.tag})');
    }
    seen[id] = e;
    final type = dartTypeFor(e.vrs);
    final tagType =
        type == null ? 'Tag' : '${e.vm == '1' ? 'One' : 'Many'}<$type>';
    (groupOnly ? plan.groupFunctions : plan.constants).add((id, e, tagType));
    if (type == null) plan.skip('untyped: VR alternatives disagree', e);
  }
  return plan;
}

/// `lib/src/tag/tags.g.dart`: the typed tag constants (C-03, DA1, S4).
String emitTags(TagPlan plan) {
  final b = StringBuffer(_header)
    ..writeln()
    ..writeln("import 'dart:typed_data';")
    ..writeln()
    ..writeln("import '../dataset/sequence.dart';")
    ..writeln("import 'tag.dart';")
    ..writeln("import 'typed_tag.dart';")
    ..writeln()
    ..writeln(
        '/// A typed constant for every keyword in the DICOM $release data')
    ..writeln('/// dictionary. The type carries the value type and whether the')
    ..writeln('/// attribute holds one value (`One`) or many (`Many`).')
    ..writeln('abstract final class DicomTags {');
  for (final (id, e, type) in plan.constants) {
    b
      ..writeln('  /// ${_doc(e)}')
      ..writeln('  static const $id = '
          '${type == 'Tag' ? 'Tag' : type}(0x${e.tag});');
  }
  for (final (id, e, type) in plan.groupFunctions) {
    final base = '0x${e.tag.substring(0, 2)}00';
    final element = '0x${e.tag.substring(4)}';
    b
      ..writeln('  /// ${_doc(e)}')
      ..writeln('  ///')
      ..writeln('  /// [group] is one of the repeating groups '
          '${e.tag.substring(0, 2)}00–${e.tag.substring(0, 2)}1E (even).')
      ..writeln('  static $type $id(int group) => '
          '${type == 'Tag' ? 'Tag' : type}(_repeating(group, $base, $element));');
  }
  b
    ..writeln()
    ..writeln('  static int _repeating(int group, int base, int element) {')
    ..writeln(
        '    if (group & 0xFF00 != base || group.isOdd || group & 0xFF > 0x1E) {')
    ..writeln("      throw ArgumentError.value(group, 'group',")
    ..writeln(
        "          'not a repeating group of \${base.toRadixString(16)}');")
    ..writeln('    }')
    ..writeln('    return group << 16 | element;')
    ..writeln('  }')
    ..writeln('}');
  return b.toString();
}

/// `lib/src/uid/uids.g.dart`: transfer syntaxes and SOP classes (C-16).
String emitUids(List<UidEntry> uids) {
  String cls(String name, String doc, Iterable<UidEntry> entries,
      {String extra = ''}) {
    final b = StringBuffer()
      ..writeln('/// $doc')
      ..writeln('abstract final class $name {');
    final seen = <String>{};
    for (final u in entries) {
      final id = identifierFor(u.keyword);
      if (!seen.add(id)) throw StateError('duplicate $name.$id');
      b
        ..writeln('  /// ${_escapeDoc(u.name)} (`${u.value}`)'
            '${u.retired ? '. Retired.' : '.'}')
        ..writeln("  static const $id = Uid('${u.value}');");
    }
    return (b
          ..write(extra)
          ..writeln('}'))
        .toString();
  }

  bool isSopClass(UidEntry u) =>
      u.type == 'SOP Class' || u.type == 'Meta SOP Class';
  final withKeyword = uids.where((u) => u.keyword.isNotEmpty);
  String list(Iterable<UidEntry> entries) =>
      entries.map((u) => '    ${identifierFor(u.keyword)},').join('\n');
  final transferSyntaxes =
      withKeyword.where((u) => u.type == 'Transfer Syntax');
  final storage = list(
      withKeyword.where((u) => isSopClass(u) && !u.retired && isStorage(u)));

  return '$_header\n'
      "import 'uid.dart';\n\n"
      '${cls('TransferSyntaxes', 'Transfer syntax UIDs (PS3.6 Table A-1).', transferSyntaxes, extra: '\n  /// Every transfer syntax in the registry, retired ones included.\n  static const all = <Uid>[\n${list(transferSyntaxes)}\n  ];\n')}\n'
      '${cls('SopClasses', 'SOP Class UIDs (PS3.6 Table A-1).', withKeyword.where(isSopClass), extra: '\n  /// Every non-retired storage SOP class.\n  static const storage = <Uid>[\n$storage\n  ];\n')}';
}

/// Storage SOP classes are named "… Storage", optionally followed by a
/// variant such as " - For Presentation".
bool isStorage(UidEntry u) => RegExp(r' Storage( - .*)?$').hasMatch(u.name);

String _doc(Element e) {
  final vr = e.vrs.map((v) => v.code).join(' or ');
  final retired = e.retired ? ' · retired' : '';
  final tag = '(${e.tag.substring(0, 4)},${e.tag.substring(4)})';
  return '${_escapeDoc(e.name)}: `${e.keyword}` $tag · $vr · VM ${e.vm}$retired';
}

String _escapeDoc(String s) =>
    s.replaceAll('[', r'\[').replaceAll(']', r'\]').replaceAll('<', '&lt;');

/// A Dart string literal for [s].
String _str(String s) {
  final escaped = s.replaceAll(r'\', r'\\').replaceAll(r'$', r'\$');
  return escaped.contains("'") && !escaped.contains('"')
      ? '"$escaped"'
      : "'${escaped.replaceAll("'", r"\'")}'";
}
